const PYTHON_INTEGER_PATTERN = /^[+-]?(?:[0-9](?:_?[0-9])*)$/;

export class InvalidPythonIntegerError extends Error {
  constructor(value) {
    super(`invalid int value: '${value}'`);
    this.name = 'InvalidPythonIntegerError';
    this.value = value;
  }
}

export function parsePythonInteger(value) {
  const text = String(value).trim();

  if (!PYTHON_INTEGER_PATTERN.test(text)) {
    throw new InvalidPythonIntegerError(value);
  }

  const negative = text.startsWith('-');
  const unsignedText = text.replace(/^[+-]/, '').replaceAll('_', '');
  const digits = unsignedText.replace(/^0+/, '') || '0';

  return digits === '0' ? '0' : `${negative ? '-' : ''}${digits}`;
}

import {
  InvalidPythonIntegerError,
  parsePythonInteger,
} from './pythonInteger.mjs';

const OPTION_DEFINITIONS = [
  { flag: '--a', key: 'a', metavar: 'A', type: 'int', required: true },
  { flag: '--b', key: 'b', metavar: 'B', type: 'str', required: true },
];

export class ArgumentParserError extends Error {
  constructor(message) {
    super(message);
    this.name = 'ArgumentParserError';
  }
}

export function renderUsage(programName) {
  return `usage: ${programName} [-h] --a A --b B`;
}

export function renderHelp(programName) {
  return `${renderUsage(programName)}\n\noptions:\n  -h, --help  show this help message and exit\n  --a A\n  --b B\n`;
}

export function formatParserError(programName, message) {
  return `${renderUsage(programName)}\n${programName}: error: ${message}`;
}

function findOption(optionName) {
  return OPTION_DEFINITIONS.find((definition) => definition.flag === optionName);
}

function isNegativeNumberToken(token) {
  return /^-[0-9]/.test(token);
}

function tokenStartsAnOption(token) {
  return token !== '-' && token.startsWith('-') && !isNegativeNumberToken(token);
}

function convertValue(definition, rawValue) {
  if (definition.type === 'str') {
    return rawValue;
  }

  try {
    return parsePythonInteger(rawValue);
  } catch (error) {
    if (error instanceof InvalidPythonIntegerError) {
      throw new ArgumentParserError(
        `argument ${definition.flag}: invalid int value: '${rawValue}'`,
      );
    }
    throw error;
  }
}

export function parseCommandLine(argv) {
  const values = {};
  const unrecognized = [];

  for (let index = 0; index < argv.length; index += 1) {
    const token = argv[index];

    if (token === '-h' || token === '--help') {
      return { action: 'help' };
    }

    const equalsIndex = token.startsWith('--') ? token.indexOf('=') : -1;
    const optionName = equalsIndex === -1 ? token : token.slice(0, equalsIndex);
    const definition = findOption(optionName);

    if (!definition) {
      unrecognized.push(token);
      continue;
    }

    let rawValue;
    if (equalsIndex !== -1) {
      rawValue = token.slice(equalsIndex + 1);
    } else {
      const nextToken = argv[index + 1];
      if (nextToken === undefined || tokenStartsAnOption(nextToken)) {
        throw new ArgumentParserError(
          `argument ${definition.flag}: expected one argument`,
        );
      }
      rawValue = nextToken;
      index += 1;
    }

    values[definition.key] = convertValue(definition, rawValue);
  }

  const missing = OPTION_DEFINITIONS
    .filter((definition) => definition.required && values[definition.key] === undefined)
    .map((definition) => definition.flag);

  if (missing.length > 0) {
    throw new ArgumentParserError(
      `the following arguments are required: ${missing.join(', ')}`,
    );
  }

  if (unrecognized.length > 0) {
    throw new ArgumentParserError(
      `unrecognized arguments: ${unrecognized.join(' ')}`,
    );
  }

  return { action: 'run', values };
}

export class Job {
  constructor(interval, unit) {
    this.interval = interval;
    this.unit = unit;
  }
}

export class JobBuilder {
  constructor(interval) {
    this.interval = interval;
  }

  get minutes() {
    return new Job(this.interval, 'minutes');
  }
}

import { JobBuilder } from './job.mjs';

export function every(interval) {
  return new JobBuilder(interval);
}

#!/usr/bin/env node

import {
  ArgumentParserError,
  formatParserError,
  parseCommandLine,
  renderHelp,
} from './lib/arguments/argparse.mjs';
import { every } from './lib/schedule/index.mjs';

function programNameFromPath(path) {
  const parts = String(path).split('/');
  return parts[parts.length - 1] || 'test3.mjs';
}

const programName = programNameFromPath(process.argv[1]);

try {
  const parsed = parseCommandLine(process.argv.slice(2));

  if (parsed.action === 'help') {
    process.stdout.write(renderHelp(programName));
  } else {
    const job = every(parsed.values.a).minutes;
    process.stdout.write(`${job.interval}\n`);
  }
} catch (error) {
  if (error instanceof ArgumentParserError) {
    process.stderr.write(`${formatParserError(programName, error.message)}\n`);
    process.exitCode = 2;
  } else {
    throw error;
  }
}

