function resolveOption(optionName) {
  if (optionName === '-h') {
    return { kind: 'help', displayName: '--help' };
  }

  const exactDefinition = OPTION_DEFINITIONS.find(
    (definition) => definition.flag === optionName,
  );
  if (exactDefinition) {
    return { kind: 'value', definition: exactDefinition };
  }

  if (optionName.startsWith('--') && optionName !== '--') {
    const matches = ['--help', ...OPTION_DEFINITIONS.map(({ flag }) => flag)]
      .filter((flag) => flag.startsWith(optionName));

    if (matches.length === 1 && matches[0] === '--help') {
      return { kind: 'help', displayName: '--help' };
    }
    if (matches.length === 1) {
      return {
        kind: 'value',
        definition: findExactOption(matches[0]),
      };
    }
    if (matches.length > 1) {
      throw new ArgumentParserError(
        `ambiguous option: ${optionName} could match ${matches.join(', ')}`,
      );
    }
  }

  return null;
}

function findExactOption(optionName) {
  return OPTION_DEFINITIONS.find((definition) => definition.flag === optionName);
}

